// Extract commit strings and capture associated Linear Issue IDs (e.g. 'ENG-105')
const items = $input.all();
const output = [];
const seen = new Set();

function pushCommit(commit) {
  if (!commit || !commit.message) return;
  const message = String(commit.message);
  const matches = message.match(/\b([A-Z][A-Z0-9]+-\d+)\b/g) || [];
  const issueIds = [...new Set(matches)];
  if (!issueIds.length) return;
  const url = commit.url || '';
  const sha = commit.id || commit.sha || '';
  const author = (commit.author && (commit.author.name || commit.author.username)) || 'unknown';
  for (const issueId of issueIds) {
    const key = issueId + '|' + sha + '|' + message;
    if (seen.has(key)) continue;
    seen.add(key);
    output.push({
      json: {
        issueId,
        commitMessage: message,
        author,
        url,
        sha,
        commentText: [
          'Automated Synchronization Success via Agent Factory Platform.',
          '',
          '**Commit:** ' + message.split('\n')[0],
          '**Author:** ' + author,
          url ? '**URL:** ' + url : null,
          sha ? '**SHA:** `' + sha + '`' : null,
          '',
          '_Healed / shipped code linked from the repository push webhook._'
        ].filter(Boolean).join('\n')
      }
    });
  }
}

for (const item of items) {
  const root = item.json || {};
  const body = root.body && typeof root.body === 'object' ? root.body : root;
  if (body.head_commit) pushCommit(body.head_commit);
  if (Array.isArray(body.commits)) {
    for (const c of body.commits) pushCommit(c);
  }
  if (typeof body.message === 'string') {
    pushCommit({
      message: body.message,
      url: body.url,
      id: body.sha || body.id,
      author: typeof body.author === 'string' ? { name: body.author } : body.author
    });
  }
}

return output;

