={
  "query": "mutation AgentFactorySync($id: String!, $commentText: String!, $stateId: String!) { issueUpdate(id: $id, input: { stateId: $stateId }) { success issue { id identifier url } } commentCreate(input: { issueId: $id, body: $commentText }) { success comment { id url } } }",
  "variables": {
    "id": "{{ $json.issueId }}",
    "commentText": {{ JSON.stringify($json.commentText) }},
    "stateId": "{{ $env.LINEAR_DONE_STATE_ID || 'DONE_STATE_ID_HERE' }}"
  }
}
